sys_script_client.script:
function onLoad() {

    //Updated for MSSTrustes-184 and 212
    // Get all fields on the form

    var allFields = g_form.getEditableFields();

    var excludedFields;
    var integrationUserList = g_scratchpad.integrationUsers; //MSSTRUSTES-165.

    if (integrationUserList.split(',').includes(g_scratchpad.openedBy)) { //MSSTRUSTES-165 for automated case
        excludedFields = ['sensitive_flag_aml_type_1_effective_date_er_risk', 'sensitive_flag_aml_type_1_er_risk', 'empf_aml_type_1_2_3_proposed_er_risk', 'fcrr_result_er_risk', 'fcrr_effective_date_er_risk', 'superhold_transaction_blocking_er_risk', 'super_trans_blocking_effective_date_er_risk', 'note_effective_date_er_risk', 'note_er_risk', 'work_notes', 'url'];
    } else { ////MSSTRUSTES-108 for manual case
        excludedFields = ['assigned_to', 'er_id', 'employer_account_type', 'sensitive_flag_aml_type_1_effective_date_er_risk', 'sensitive_flag_aml_type_1_er_risk', 'empf_aml_type_1_2_3_proposed_er_risk', 'fcrr_result_er_risk', 'fcrr_effective_date_er_risk', 'superhold_transaction_blocking_er_risk', 'super_trans_blocking_effective_date_er_risk', 'note_effective_date_er_risk', 'note_er_risk', 'identification_hkid_card_auth_pers_1', 'identification_passportno_auth_pers_1', 'work_notes', 'url', 'member_account_type_1_ee', 'scheme_code'];
    }


    // Loop through all fields and make them read-only, except the excluded ones

    var assignedTo = g_form.getValue('assigned_to');
    var currUser = g_user.userID;


    if (g_form.isNewRecord()) {
        allFields.forEach(function(field) {
                if (!excludedFields.includes(field)) {
                    g_form.setReadOnly(field, true);
                }
            });
    } else {
        if (currUser == assignedTo) {
			alert('in else Kovd');
            allFields.forEach(function(field) {
                if (!excludedFields.includes(field)) {
                    g_form.setReadOnly(field, true);
					alert('in else - Kovd');
                }
            });
			alert('in else 2 Kovd');
            g_form.setMandatory('fcrr_result_er_risk', true);
            g_form.setMandatory('fcrr_effective_date_er_risk', true);

         }// else {
        //     allFields.forEach(function(field) {
		// 		alert('in else 44 Kovd');
        //         g_form.setReadOnly(field, true);
        //     });
        // }
    }

    // If ops_admin, make assigned_to editable //MSSTRUSTES-252.
    if (g_user.hasRole('x_hsb11_mss_trus_0.ops_admin')) {
        g_form.setReadOnly('assigned_to', false);
    }
}
